import { describe, it } from "node:test";
import assert from "node:assert";
import { rateLimitHeaders } from "../src/ratelimit.js";

describe("rateLimitHeaders", () => {
  it("sends X-RateLimit-Reset as Unix timestamp and Retry-After as relative seconds", () => {
    const now = new Date("2024-01-15T12:00:00.000Z");
    const resetInSeconds = 300;
    const headers = rateLimitHeaders(100, 50, resetInSeconds, now);

    const expectedTimestamp = Math.floor(now.getTime() / 1000) + resetInSeconds;

    assert.strictEqual(headers["X-RateLimit-Limit"], "100");
    assert.strictEqual(headers["X-RateLimit-Remaining"], "50");
    assert.strictEqual(headers["X-RateLimit-Reset"], String(expectedTimestamp));
    assert.strictEqual(headers["Retry-After"], "300");
  });

  it("clamps remaining to 0 when negative", () => {
    const headers = rateLimitHeaders(100, -5, 60);
    assert.strictEqual(headers["X-RateLimit-Remaining"], "0");
  });
});

